import Dataman from"./dataman.js";class Ajax{constructor(t="anonymous"){this.session_token=t,this.dataman=new Dataman,this.ipfs_gateway="https://gateway.ipfs-upload.com/ipfs/"}async go(t,e,a="POST"){const s={method:a,headers:{"Content-type":"application/x-www-form-urlencoded"}};"GET"!==a&&(s.body=e);const n=await fetch(t,s);if(!n.ok)throw new Error(`HTTP error! status: ${n.status}`);return await n.text()}async head(t){return this.go(t,{},"HEAD")}async blob(t,e){const a=await fetch(t,{method:"POST",headers:{"Content-type":"application/x-www-form-urlencoded"},body:e});if(!a.ok)throw new Error(`HTTP error! status: ${a.status}`);return await a.json()}async json(t,e={}){e.session_token=this.session_token;var a=[];for(var s in e)a.push(encodeURIComponent(s)+"="+encodeURIComponent(e[s]));const n=await this.go(t,a.join("&"));try{return JSON.parse(n)}catch(t){return n}}ipfs=async t=>{try{const e=`${this.ipfs_gateway}${t}`,a=await fetch(e);switch(a.headers.get("content-type").toLowerCase()){case"application/json; charset=utf-8":case"text/html; charset=utf-8":case"application/json":return a.json();break;default:return a.blob();break}}catch(t){}};async post(t,e){return await this.json(t,e)}async form(t,e){const a=this;var s=new XMLHttpRequest;s.onreadystatechange=function(){if(4==s.readyState)return result=a.parseJSON(s.responseText),result},s.open("POST",t,!0),s.send(e)}}export default Ajax;